package com.hbm.machine.reactor.rbmk.fuel;
import java.util.*;import com.hbm.hazard.HbmHazards;import com.hbm.machine.reactor.WastePlateEntity;import net.minecraft.ChatFormatting;import net.minecraft.network.chat.Component;import net.minecraft.world.entity.Entity;import net.minecraft.world.item.*;import net.minecraft.world.level.Level;
/** Real ItemRBMKPellet extends source waste-item behavior and exact enrichment/xenon pass semantics. */
public final class RbmkPelletItem extends Item {
 public final String variant,fullName;private boolean hasXenon=true;public RbmkPelletItem(String variant,String fullName){super(new Properties().component(HbmHazards.LEGACY_METADATA.get(),0));this.variant=variant;this.fullName=fullName;}public RbmkPelletItem disableXenon(){hasXenon=false;return this;}public boolean isXenonEnabled(){return hasXenon;}public static int rectify(int metadata){return Math.abs(metadata)%10;}public static boolean hasXenon(int metadata){return rectify(metadata)>=5;}public int metadata(ItemStack stack){return rectify(stack.getOrDefault(HbmHazards.LEGACY_METADATA.get(),0));}public List<ItemStack> creativeStacks(){var result=new ArrayList<ItemStack>();for(int i=0;i<(hasXenon?10:5);i++){var stack=new ItemStack(this);stack.set(HbmHazards.LEGACY_METADATA.get(),i);result.add(stack);}return List.copyOf(result);}
 @Override public Component getName(ItemStack stack){return Component.translatable("item.rbmk_pellet_"+variant+".name");}@Override public void appendHoverText(ItemStack stack,TooltipContext context,List<Component> lines,TooltipFlag flag){var composition=Component.translatable("rbmk.fuel."+variant+".composition").withStyle(ChatFormatting.ITALIC);if(variant.equals("drx"))composition.withStyle(ChatFormatting.OBFUSCATED);lines.add(composition);lines.add(Component.translatable("rbmk.pellet.recycling").withStyle(ChatFormatting.DARK_GRAY,ChatFormatting.ITALIC));int metadata=metadata(stack);ChatFormatting[] colors={ChatFormatting.GOLD,ChatFormatting.YELLOW,ChatFormatting.GREEN,ChatFormatting.DARK_GREEN,ChatFormatting.DARK_GRAY};lines.add(Component.translatable("rbmk.pellet.depletion."+(metadata%5)).withStyle(colors[metadata%5]));if(hasXenon(metadata))lines.add(Component.translatable("rbmk.pellet.xenon").withStyle(ChatFormatting.DARK_PURPLE));}
 @Override public boolean hasCustomEntity(ItemStack stack){return true;}@Override public int getEntityLifespan(ItemStack stack,Level level){return Integer.MAX_VALUE;}@Override public Entity createEntity(Level level,Entity original,ItemStack stack){var waste=new WastePlateEntity(level,original.getX(),original.getY(),original.getZ(),stack);waste.setDeltaMovement(original.getDeltaMovement());waste.setPickUpDelay(10);original.discard();return waste;}
}
